def drive(me, enemy, arena):
    # If we can't drive, stop
    if not me.can_drive:
        return (0, 0)

    # Calculate direction to enemy
    dx = enemy.x - me.x
    dy = enemy.y - me.y
    dist = (dx**2 + dy**2)**0.5

    # If very close, back up slightly
    if dist < 0.5:
        return (-0.3, -0.3)

    # Angle to enemy relative to our heading
    enemy_angle = math.atan2(dy, dx) * 180 / math.pi
    angle_diff = enemy_angle - me.heading
    # Normalize to -180 to 180
    angle_diff = ((angle_diff + 180) % 360) - 180

    # If enemy is mostly ahead, drive forward and turn toward it
    if abs(angle_diff) < 90:
        # Forward throttle decreases with distance
        forward = 1.0 if dist > 3.0 else 0.5
        # Turn toward enemy (negative = left)
        turn = -angle_diff / 180.0
        turn = max(-1.0, min(1.0, turn))
        left = forward + turn
        right = forward - turn
        # Clamp to [-1, 1]
        left = max(-1.0, min(1.0, left))
        right = max(-1.0, min(1.0, right))
        return (left, right)
    else:
        # Turn toward enemy first
        turn = -angle_diff / 180.0
        turn = max(-1.0, min(1.0, turn))
        return (0.3 * turn, -0.3 * turn)

