    # Try to self-right if inverted
    if me.inverted and me.invertible and not me.righting:
        # Check for flipper on front or back
        for slot in ["front", "back"]:
            w = me.weapons.get(slot, {})
            if w.get("type") == "flipper" and w.get("ready", False):
                # Flipper can self-right from upside down
                if enemy.on_side and not enemy.righting:
                    return "flip(" + slot + ")"
                # Also try if we're just inverted and need to recover
                if not enemy.righting:
                    return "flip(" + slot + ")"

        # Check for lifter on front or back
        for slot in ["front", "back"]:
            w = me.weapons.get(slot, {})
            if w.get("type") == "lifter" and w.get("state", "") == "down":
                if not enemy.airborne and not enemy.held and enemy.z < 0.5:
                    return "lift(" + slot + ")"

    # Try to use clamp if available
    for slot in ["front", "back"]:
        w = me.weapons.get(slot, {})
        if w.get("type") == "clamp":
            if w.get("state", "") == "open":
                # Try to grab if enemy is vulnerable
                if enemy.z < 0.3 or enemy.on_side or enemy.inverted:
                    return "grab(" + slot + ")"
            elif w.get("state", "") == "holding":
                if arena.time - last_grab_time > 5.0 if 'last_grab_time' in globals() else True:
                    return "release(" + slot + ")"

    # Try spinner if available
    for slot in ["front", "back"]:
        w = me.weapons.get(slot, {})
        if w.get("type") == "spinner":
            current_rpm = w.get("rpm", 0)
            # Spin up if not at target
            if abs(current_rpm) < 2000:
                target_rpm = 3000 if current_rpm >= 0 else -3000
                return "spin(" + slot + ", " + str(target_rpm) + ")"
            # Once at speed, maintain
            elif abs(current_rpm) < 8000:
                # Keep spinning at current speed
                return None

    # Try hammer swing if ready and enemy is within range
    if me.weapons.get("top", {}).get("type") == "hammer":
        w = me.weapons.get("top", {})
        if w.get("state", "") == "ready":
            # Check if enemy is at reasonable height and not protected
            if enemy.z < 0.6 and not enemy.righting and not enemy.held:
                # Check horizontal distance
                dx = enemy.x - me.x
                if abs(dx) < 1.5:
                    return "swing(" + "top" + ")"

    # Try flipper attack if ready and enemy is at rest
    for slot in ["front", "back"]:
        w = me.weapons.get(slot, {})
        if w.get("type") == "flipper" and w.get("ready", False):
            # Check if enemy is at rest and not airborne
            if enemy.z < 0.3 and not enemy.airborne and not enemy.held:
                return "flip(" + slot + ")"

    # Try lifter attack if ready
    for slot in ["front", "back"]:
        w = me.weapons.get(slot, {})
        if w.get("type") == "lifter" and w.get("state", "") == "down":
            # Check if enemy is over the forks area
            if not enemy.airborne and not enemy.held and enemy.z < 0.3:
                return "lift(" + slot + ")"

    return None

